cardCss:
/* ==========================================================================
   English Word Card (Simple) · 轻立体 + 翡翠
   --------------------------------------------------------------------------
   外观 = 预览定稿版（_preview/v2_light3d_view.html 的「乙 · 翡翠」）。
   颜色全部走 --ew-* 变量：暗色皮肤只重映射变量，规则一条不改。
   结构由 cardJs 生成（类名不变），本文件只管外观。
   ========================================================================== */

/* ---------- 1. 配色（浅色） ---------- */
.dc-card.ew {
  color: var(--ew-ink);
  --ew-h1:#059669; --ew-h2:#0891b2;                 /* 主色 / 第二色：渐变脊 · 序号章 · 音标 */
  --ew-h1-deep:#065f46; --ew-h1-soft:#ecfdf5; --ew-h1-ink:#022c22;
  --ew-h1-sh:rgba(5,150,105,.34);
  --ew-warm:#ea580c; --ew-warm-soft:#fff6f0; --ew-warm-ink:#3a1d0c;   /* 中文释义走暖色，中英不用加标签 */
  --ew-ink:#065f46;                                  /* 单词 */
  --ew-play:#059669; --ew-play-bg:#ecfdf5; --ew-play-line:#a7f3d0; --ew-play-sh:rgba(5,150,105,.30);
  --ew-mark:#e11d48; --ew-mark-bg:#fff1f2; --ew-mark-line:#fecdd3; --ew-mark-sh:rgba(225,29,72,.30);
  --ew-fav:#d97706;  --ew-fav-bg:#fffbeb;  --ew-fav-line:#fde68a; --ew-fav-sh:rgba(217,119,6,.30);
  /* 卡面 / 投影 / 按钮 */
  --ew-c1:#ffffff; --ew-c2:#fcfdff;
  --ew-card-line:rgba(15,23,42,.07);
  --ew-card-sh:0 1px 2px rgba(15,23,42,.04),0 10px 22px -15px rgba(15,23,42,.26);
  --ew-card-sh-up:0 2px 4px rgba(15,23,42,.05),0 18px 32px -18px rgba(15,23,42,.32);
  --ew-btn-bg:#ffffff; --ew-btn-line:#e2e8f0; --ew-btn-sh:0 1.5px 3px rgba(15,23,42,.07);
  --ew-btn-inset:inset 0 1px 0 rgba(255,255,255,.9);
  --ew-def-bg:rgba(255,255,255,.74);
}

/* ---------- 2. 尺寸：按钮 68px（闪卡 56px），随应用字号一起放大 ---------- */
.dc-card.ew {
  --ew-scale: clamp(1,(var(--card-font-scale,1) - 1)*.55 + 1,1.45);
  --ew-idx:   calc(var(--scale-basic,1)*var(--card-font-scale,1));   /* 序号章等"跟字走"的盒子用它换算尺寸 */
  --ew-btn:    calc(68px*var(--ew-scale));
  --ew-btn-sm: calc(56px*var(--ew-scale));
}

/* ---------- 3. 卡面：轻轻浮起 + 右上角淡主色光晕 + 左侧双色渐变脊 ---------- */
.dc-card.ew {
  position:relative; isolation:isolate; overflow:hidden; padding:16px;
  background:
    radial-gradient(130% 105% at 100% 0%, var(--ew-h1-soft) 0%, rgba(255,255,255,0) 58%),
    linear-gradient(180deg, var(--ew-c1) 0%, var(--ew-c2) 100%);
  border:1px solid var(--ew-card-line); border-radius:18px;
  box-shadow:var(--ew-card-sh);
  transition:transform .2s cubic-bezier(.2,.7,.3,1),box-shadow .2s;
}
/* overflow:hidden 会把这道脊裁进圆角，否则四角会戳出来一小块 */
.dc-card.ew::before {
  content:''; position:absolute; left:0; top:0; bottom:0; width:4px; z-index:4;
  background:linear-gradient(180deg,var(--ew-h1) 0%,var(--ew-h2) 100%);
  pointer-events:none;
}
.dc-card.ew:hover { transform:translateY(-2px); box-shadow:var(--ew-card-sh-up); }
.dc-card.ew.flash { min-height:340px; padding:0; background:var(--ew-c1); }

/* ---------- 4. 序号 / 单词 / 音标 ---------- */
/* 序号徽章是一枚"胶囊"，尺寸必须跟着字号走（--ew-idx 见上面的尺寸块）。
   原来字号写死 11px：应用字号调到 160% 时徽章还是 11px，跟旁边的词不成比例。 */
.dc-card.ew .ew-index {
  display:inline-grid; place-items:center;
  min-width:calc(27px*var(--ew-idx)); height:calc(21px*var(--ew-idx)); padding:0 calc(7px*var(--ew-idx));
  border-radius:calc(8px*var(--ew-idx)); font-size:calc(11px*var(--ew-idx)); font-weight:800;
  letter-spacing:calc(.4px*var(--ew-idx)); color:#fff;
  background:linear-gradient(135deg,var(--ew-h1) 0%,var(--ew-h2) 100%);
  box-shadow:0 3px 8px -2px var(--ew-h1-sh);
}
.dc-card.ew .ew-word { color:var(--ew-ink); letter-spacing:.2px; }
.dc-card.ew .ew-phon {
  color:var(--ew-h1-deep); background:var(--ew-h1-soft);
  border-radius:9999px; padding:1px 9px; font-weight:600;
}

/* ---------- 5. 按钮：三个动作三种语义色，描边白底 → hover 实心 ---------- */
.dc-card.ew .dc-act {
  width:var(--ew-btn); height:var(--ew-btn);
  font-size:calc(var(--ew-btn)*.40);
  display:grid; place-items:center; border-radius:9999px; cursor:pointer;
  background:var(--ew-btn-bg); border:1.5px solid var(--ew-btn-line);
  box-shadow:var(--ew-btn-sh),var(--ew-btn-inset);
  transition:transform .16s cubic-bezier(.2,.7,.3,1),box-shadow .16s,
             background .16s,color .16s,border-color .16s;
}
/* 光学居中：FA7 的 webfont 字形在 em 方框里系统性偏上（实测 2.2~3.6px），
   只让 <i> 盒子居中是不够的。按 em 补偿，随字号自动缩放。 */
.dc-card.ew .dc-act > i { display:block; line-height:1; transform:translateY(.125em); }
.dc-card.ew .dc-act.act-fav > i { transform:translateY(.077em); }   /* 星星偏上较少 */

.dc-card.ew .dc-act.act-play { color:var(--ew-play); background:var(--ew-play-bg); border-color:var(--ew-play-line); }
.dc-card.ew .dc-act.act-mark { color:var(--ew-mark); background:var(--ew-mark-bg); border-color:var(--ew-mark-line); }
.dc-card.ew .dc-act.act-fav  { color:var(--ew-fav);  background:var(--ew-fav-bg);  border-color:var(--ew-fav-line); }

.dc-card.ew .dc-act.act-play:hover { background:var(--ew-play); color:#fff; border-color:var(--ew-play);
                                     transform:translateY(-2px); box-shadow:0 7px 15px -4px var(--ew-play-sh); }
.dc-card.ew .dc-act.act-mark:hover { background:var(--ew-mark); color:#fff; border-color:var(--ew-mark);
                                     transform:translateY(-2px); box-shadow:0 7px 15px -4px var(--ew-mark-sh); }
.dc-card.ew .dc-act.act-fav:hover  { background:var(--ew-fav);  color:#fff; border-color:var(--ew-fav);
                                     transform:translateY(-2px); box-shadow:0 7px 15px -4px var(--ew-fav-sh); }
.dc-card.ew .dc-act:active { transform:translateY(0) scale(.93); box-shadow:0 1px 2px rgba(15,23,42,.14); }

.dc-card.ew .dc-act.act-mark.is-active { background:var(--ew-mark); border-color:var(--ew-mark); color:#fff;
                                         box-shadow:0 5px 13px -3px var(--ew-mark-sh); }
.dc-card.ew .dc-act.act-fav.is-active  { background:var(--ew-fav);  border-color:var(--ew-fav);  color:#fff;
                                         box-shadow:0 5px 13px -3px var(--ew-fav-sh); }

/* ---------- 6. 释义块：中文暖色 / 英文冷色。两块 border-left 宽度与 padding 相同，
   所以文本起点严格对齐（旧版差 17px，看着"错位"）。 ---------- */
.dc-card.ew .dc-scroll { scrollbar-width:thin; scrollbar-color:var(--line) transparent; }
.dc-card.ew .dc-scroll::-webkit-scrollbar { width:8px; }
.dc-card.ew .dc-scroll::-webkit-scrollbar-thumb { background:var(--line); border-radius:8px; }

.dc-card.ew .dc-scroll > div {
  border-radius:12px; padding:10px 14px;
  border-left:3px solid var(--ew-warm);
  background:var(--ew-warm-soft); color:var(--ew-warm-ink);
  box-shadow:0 1px 2px rgba(15,23,42,.03);
}
.dc-card.ew .dc-scroll > .ew-def-en {
  border-left-color:var(--ew-h1); background:var(--ew-h1-soft); color:var(--ew-h1-ink);
}

/* ---------- 7. 闪卡（已标记）：正面冷色、背面暖色 ---------- */
.dc-card.ew .ew-flash { perspective:1400px; width:100%; height:100%; min-height:340px;
                        position:relative; display:flex; flex-direction:column; }
.dc-card.ew .ew-flash-inner { position:relative; width:100%; flex:1; min-height:0;
                              transform-style:preserve-3d; transition:transform .5s cubic-bezier(.4,.2,.2,1); }
.dc-card.ew .ew-flash.flipped .ew-flash-inner { transform:rotateY(180deg); }
.dc-card.ew .ew-face { position:absolute; inset:0; backface-visibility:hidden;
                       -webkit-backface-visibility:hidden; display:flex; flex-direction:column; overflow-y:auto; }
.dc-card.ew .ew-front { padding:18px 16px; background:linear-gradient(165deg,var(--ew-h1-soft) 0%,var(--ew-c1) 58%); }
.dc-card.ew .ew-back  { transform:rotateY(180deg); padding:18px 16px;
                        background:linear-gradient(165deg,var(--ew-warm-soft) 0%,var(--ew-c1) 58%); }
.dc-card.ew .ew-flash-head { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; margin-bottom:10px; }
.dc-card.ew .ew-flash-badge {
  display:inline-flex; align-items:center; gap:5px; font-size:11px; font-weight:700;
  color:var(--ew-mark); background:var(--ew-mark-bg); border:1px solid var(--ew-mark-line);
  border-radius:20px; padding:3px 10px; box-shadow:0 1px 2px rgba(15,23,42,.05);
}
.dc-card.ew .ew-flash-actions { display:flex; gap:8px; }
.dc-card.ew .ew-flash-actions .dc-act { width:var(--ew-btn-sm); height:var(--ew-btn-sm);
                                        font-size:calc(var(--ew-btn-sm)*.40); }
.dc-card.ew .ew-flash-body { flex:1; display:flex; flex-direction:column; align-items:center;
                             justify-content:center; text-align:center; gap:10px; min-height:0; cursor:pointer; }
.dc-card.ew .ew-flash-word { font-size:calc(34px*var(--card-font-scale,1)); font-weight:800; color:var(--ew-ink);
                             letter-spacing:.5px; line-height:1.3; word-break:break-word; }
.dc-card.ew .ew-flash-phon { font-size:calc(16px*var(--card-font-scale,1)); color:var(--ew-h1-deep);
                             background:var(--ew-h1-soft); border-radius:9999px; padding:2px 11px; font-weight:600; }
.dc-card.ew .ew-back-body { flex:1; display:flex; flex-direction:column; justify-content:center; gap:14px; text-align:left; }
.dc-card.ew .ew-back-word { font-size:calc(34px*var(--card-font-scale,1)); font-weight:800; color:var(--ew-ink);
                            letter-spacing:.5px; line-height:1.3; word-break:break-word; }
.dc-card.ew .ew-back-def {
  font-size:calc(16px*var(--card-font-scale,1)); line-height:1.8;
  background:var(--ew-def-bg); border:1px solid var(--ew-card-line);
  border-left:3px solid var(--ew-warm); border-radius:12px; padding:10px 14px;
  color:var(--ew-warm-ink); box-shadow:0 1px 2px rgba(15,23,42,.04);
}
.dc-card.ew .ew-back-def.ew-def-en { border-left-color:var(--ew-h1); color:var(--ew-h1-ink); }
.dc-card.ew .ew-back-hint { font-size:12px; color:var(--ew-h1-deep); cursor:pointer; padding:6px; }
.dc-card.ew .ew-back-hint:hover { color:var(--ew-h1); }

/* ---------- 8. 窄屏（手机）：三个大按钮 + 长单词塞不进一行。
   应用的移动端断点就是 640px，此时卡片内宽只有约 307px，
   3×68px 的按钮要 220px，长单词必被截断（旧版 60px 时也一样）。
   让按钮整组独占一行、均匀铺开 —— 布局恒定，不随单词长短跳。 ---------- */
@media (max-width:640px) {
  .dc-card.ew:not(.flash) > div:not(.dc-scroll) { flex-wrap:wrap; row-gap:12px; }
  .dc-card.ew:not(.flash) > div:not(.dc-scroll) > div:last-child { flex:1 0 100%; justify-content:space-between; }
  /* 闪卡不能 wrap：内层 .ew-flash 是 column flex，加 wrap 会多长出一列 */
}

/* ---------- 9. 暗色皮肤（dark / starry / scifi）：只重映射变量 ---------- */
body.dark-mode .dc-card.ew {
  --ew-h1-deep:#6ee7b7; --ew-h1-soft:rgba(5,150,105,.20); --ew-h1-ink:#d1fae5;
  --ew-h1-sh:rgba(5,150,105,.45);
  --ew-warm-soft:rgba(234,88,12,.16); --ew-warm-ink:#fed7aa;
  --ew-ink:#a7f3d0;
  --ew-play-bg:rgba(5,150,105,.16); --ew-play-line:rgba(110,231,183,.34);
  --ew-mark-bg:rgba(225,29,72,.16); --ew-mark-line:rgba(253,164,175,.30);
  --ew-fav-bg:rgba(217,119,6,.16);  --ew-fav-line:rgba(252,211,77,.30);
  --ew-c1:var(--card-bg); --ew-c2:var(--card-bg);
  --ew-card-line:var(--line);
  --ew-card-sh:0 1px 2px rgba(0,0,0,.35),0 12px 26px -16px rgba(0,0,0,.75);
  --ew-card-sh-up:0 2px 4px rgba(0,0,0,.40),0 20px 34px -18px rgba(0,0,0,.80);
  --ew-btn-bg:rgba(255,255,255,.05); --ew-btn-line:var(--line); --ew-btn-sh:0 1px 2px rgba(0,0,0,.30);
  --ew-btn-inset:inset 0 1px 0 rgba(255,255,255,.06);
  --ew-def-bg:rgba(255,255,255,.06);
}

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    function parseList(t) {
        if (t == null) return [];
        if (Array.isArray(t)) return t;
        if (typeof t !== 'string') return [String(t)];
        try {
            var arr = JSON.parse(t);
            if (Array.isArray(arr)) return arr;
        } catch (e) {}
        return [t];
    }
    function defBlock(items, extraClass) {
        if (!items.length) return '';
        var html = '<div class="' + (extraClass || '') + '" style="font-size:calc(16px*var(--card-font-scale,1));line-height:1.8">';
        items.forEach(function (t) { html += '<div>' + esc(t) + '</div>'; });
        html += '</div>';
        return html;
    }
    window.cardTemplate = {
        name: 'English Word (Simple)',
        fields: [
            { key: 'word', label: '单词', hideable: false },
            { key: 'phonetic_us', label: '音标' },
            { key: 'paraphrase_en', label: '英文释义' },
            { key: 'paraphrase_zh', label: '中文释义' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function h(k, html) { return isHidden(k) ? '' : html; }

            var markActive = data.is_unknown === 1 ? ' is-active' : '';
            var favActive = data.is_favorite === 1 ? ' is-active' : '';
            var isMarked = data.is_unknown === 1;

            /* ---- Normal card (unmarked): word + phonetic + both definitions ---- */
            if (!isMarked) {
                var html = '';
                html += '<div class="dc-card ew flex flex-col max-h-[560px] bg-[var(--card-bg)] text-[var(--ink)] border border-[var(--line)] rounded-2xl p-4 shadow-sm mb-4" data-card-id="' + data.id + '">';
                html += '<div class="flex items-start justify-between gap-3 mb-3 shrink-0">';
                html += '<div class="flex items-baseline gap-2 flex-wrap min-w-0">';
                html += '<span class="ew-index text-xs font-semibold">' + String(data.current_order).padStart(2, '0') + '</span>';
                html += h('word', '<span class="ew-word text-2xl font-bold" style="font-size:calc(24px*var(--card-font-scale,1))">' + esc(d.word) + '</span>');
                html += h('phonetic_us', '<span class="ew-phon text-sm" style="font-size:calc(13px*var(--card-font-scale,1))">/' + esc(d.phonetic_us) + '/</span>');
                html += '</div>';
                html += '<div class="flex items-center gap-2 shrink-0">';
                html += '<button class="dc-act act-play" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>';
                html += '<button class="dc-act act-mark' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>';
                html += '<button class="dc-act act-fav' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
                html += '</div></div>';
                html += '<div class="dc-scroll flex-1 min-h-0 overflow-y-auto space-y-3">';
                html += defBlock(parseList(d.paraphrase_zh), '');
                html += defBlock(parseList(d.paraphrase_en), 'ew-def-en');
                html += '</div></div>';
                return html;
            }

            /* ---- Flashcard (marked): front = word+phonetic, back = definitions ---- */
            var flipped = data._flashFlipped === true;
            var wordHtml = h('word', '<div class="ew-flash-word">' + esc(d.word) + '</div>');
            var phonHtml = h('phonetic_us', '<div class="ew-flash-phon">/' + esc(d.phonetic_us) + '/</div>');

            var frontDefs = '';
            if (!isHidden('paraphrase_zh') && parseList(d.paraphrase_zh).length) {
                frontDefs += '<div class="ew-back-def">' + parseList(d.paraphrase_zh).map(esc).join('<br>') + '</div>';
            }
            if (!isHidden('paraphrase_en') && parseList(d.paraphrase_en).length) {
                frontDefs += '<div class="ew-back-def ew-def-en">' + parseList(d.paraphrase_en).map(esc).join('<br>') + '</div>';
            }

            var html = '';
            html += '<div class="dc-card ew flash flex flex-col bg-[var(--card-bg)] text-[var(--ink)] border border-[var(--line)] rounded-2xl shadow-sm mb-4 highlighted" data-card-id="' + data.id + '">';
            html += '<div class="ew-flash' + (flipped ? ' flipped' : '') + '">';
            html += '<div class="ew-flash-inner">';
            /* Front face */
            html += '<div class="ew-face ew-front">';
            html += '<div class="ew-flash-head">';
            html += '<div class="ew-flash-badge"><i class="fa-solid fa-layer-group"></i> ' + (data.current_order ? String(data.current_order).padStart(2, '0') : '') + ' · 闪卡</div>';
            html += '<div class="ew-flash-actions">';
            html += '<button class="dc-act act-play" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>';
            html += '<button class="dc-act act-mark' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>';
            html += '<button class="dc-act act-fav' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>';
            html += '</div></div>';
            html += '<div class="ew-flash-body" data-action="flip">';
            html += wordHtml;
            html += phonHtml;

            html += '</div>';
            html += '</div>';
            /* Back face */
            html += '<div class="ew-face ew-back">';
            html += '<div class="ew-back-body" data-action="flip">';
            html += '<div class="ew-back-word">' + esc(d.word) + '</div>';
            html += frontDefs;

            html += '</div>';
            html += '</div>';
            html += '</div></div></div>';
            return html;
        },
        init: function (cardElement, cardData, api) {
            var pb = cardElement.querySelector('[data-action="play"]');
            if (pb) pb.addEventListener('click', function () {
                var d = (api.getCardData().data) || {};
                api.playAudio(d.word || '');
                api.track('audio_play');
            });
            var mb = cardElement.querySelector('[data-action="mark"]');
            if (mb) mb.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var fb = cardElement.querySelector('[data-action="favorite"]');
            if (fb) fb.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
            /* Flashcard flip: record definition_view when revealing the back,
               but NOT when flipping back to the front. */
            cardElement.querySelectorAll('[data-action="flip"]').forEach(function (el) {
                el.addEventListener('click', function () {
                    var d = api.getCardData();
                    var wasFlipped = d._flashFlipped === true;
                    d._flashFlipped = !wasFlipped;
                    if (!wasFlipped) api.track('definition_view');
                    api.rerender();
                });
            });
            cardElement.querySelectorAll('[data-action]').forEach(function (btn) {
                btn.addEventListener('mouseenter', function () {
                    var t = btn.dataset.tooltip; if (t && api.showTooltip) api.showTooltip(btn, t);
                });
                btn.addEventListener('mouseleave', function () { if (api.hideTooltip) api.hideTooltip(); });
            });
        }
    };
})();
